INSERT INTO "metrics" VALUES('assets','Consolidated total assets.','instant');
INSERT INTO "metrics" VALUES('borrowings_current','Borrowings excluding separately shown leases; current. Carrying value, not necessarily contractual principal.','instant');
INSERT INTO "metrics" VALUES('borrowings_noncurrent','Borrowings excluding separately shown leases; noncurrent. Carrying value, not necessarily contractual principal.','instant');
INSERT INTO "metrics" VALUES('capex','Positive cash capital expenditure; purchase deposits, intangibles, netting and capitalised interest differ as noted.','duration');
INSERT INTO "metrics" VALUES('cash','Cash/cash equivalents or cash-and-bank line as stated; unrestricted availability not yet assessed.','instant');
INSERT INTO "metrics" VALUES('cash_and_investments','Issuer cash/investment or liquidity aggregate; not equivalent to unrestricted cash.','instant');
INSERT INTO "metrics" VALUES('cfo','Net cash from operating activities as reported. Interest/dividend classification varies by issuer.','duration');
INSERT INTO "metrics" VALUES('crew_cost','Crew cost subset; do not add to total staff cost.','duration');
INSERT INTO "metrics" VALUES('debt_finance_leases_current','Debt and finance lease obligations (other financial liabilities may be included as noted); current. Carrying value, not necessarily contractual principal.','instant');
INSERT INTO "metrics" VALUES('debt_finance_leases_noncurrent','Debt and finance lease obligations (other financial liabilities may be included as noted); noncurrent. Carrying value, not necessarily contractual principal.','instant');
INSERT INTO "metrics" VALUES('debt_including_leases_current','Combined debt and lease liabilities; current. Carrying value, not necessarily contractual principal.','instant');
INSERT INTO "metrics" VALUES('debt_including_leases_noncurrent','Combined debt and lease liabilities; noncurrent. Carrying value, not necessarily contractual principal.','instant');
INSERT INTO "metrics" VALUES('depreciation_amortisation','Depreciation/amortisation subtotal; impairment/provisions included only as noted.','duration');
INSERT INTO "metrics" VALUES('equity','Total consolidated book equity including non-controlling interests and equity-classified hybrids where applicable.','instant');
INSERT INTO "metrics" VALUES('equity_parent','Equity attributable to parent owners only; not substituted for total equity.','instant');
INSERT INTO "metrics" VALUES('equity_perpetuals','Equity-classified perpetual securities subset; already included in equity.','instant');
INSERT INTO "metrics" VALUES('finance_costs','Broad finance costs; may include FX, valuation or unwinding charges. Not a uniform interest denominator.','duration');
INSERT INTO "metrics" VALUES('fuel_cost','Reported fuel expense including hedges or SAF only where indicated; not a uniform unhedged fuel measure.','duration');
INSERT INTO "metrics" VALUES('fuel_financing','Separate fuel financing liability; excluded from the selected debt/lease carrying subtotal.','instant');
INSERT INTO "metrics" VALUES('general_admin','General and administration expense separately disclosed below issuer operating subtotal.','duration');
INSERT INTO "metrics" VALUES('interest_expense','Gross interest expense as disclosed, distinct from broad finance costs and net interest.','duration');
INSERT INTO "metrics" VALUES('interest_expense_net_capitalised','Interest expense after capitalised interest, before interest income.','duration');
INSERT INTO "metrics" VALUES('interest_net','Net interest expense as disclosed; do not treat as gross interest.','duration');
INSERT INTO "metrics" VALUES('issuer_debt','Issuer debt headline with source-specific perimeter; not automatically used in derived leverage.','instant');
INSERT INTO "metrics" VALUES('leases_current','IFRS lease liabilities; current. Carrying value, not necessarily contractual principal.','instant');
INSERT INTO "metrics" VALUES('leases_fleet','Fleet leases subset only; not total lease liabilities.','instant');
INSERT INTO "metrics" VALUES('leases_noncurrent','IFRS lease liabilities; noncurrent. Carrying value, not necessarily contractual principal.','instant');
INSERT INTO "metrics" VALUES('net_profit','Consolidated net profit/loss after tax including non-controlling interests.','duration');
INSERT INTO "metrics" VALUES('net_profit_parent','Profit/loss attributable to parent owners; not substituted for consolidated profit.','duration');
INSERT INTO "metrics" VALUES('operating_expenses','Issuer operating expense subtotal or stated arithmetic aggregation; see notes for included other income.','duration');
INSERT INTO "metrics" VALUES('operating_expenses_reported','Issuer partial expense subtotal; further operating charges excluded.','duration');
INSERT INTO "metrics" VALUES('operating_leases_current','US GAAP operating lease liabilities; current. Carrying value, not necessarily contractual principal.','instant');
INSERT INTO "metrics" VALUES('operating_leases_noncurrent','US GAAP operating lease liabilities; noncurrent. Carrying value, not necessarily contractual principal.','instant');
INSERT INTO "metrics" VALUES('operating_profit','Issuer statutory operating result as mapped; scope differences retained in report notes. Not adjusted EBIT.','duration');
INSERT INTO "metrics" VALUES('operating_profit_reported','Issuer operating subtotal that excludes further operating charges; unsuitable for a comparable EBIT margin.','duration');
INSERT INTO "metrics" VALUES('other_operating_income','Other operating income, sometimes net of operating charges as explicitly noted.','duration');
INSERT INTO "metrics" VALUES('revenue','Issuer consolidated revenue; other income included where stated in observation notes. No FX conversion.','duration');
INSERT INTO "metrics" VALUES('short_term_investments','Separate deposits/securities; eligibility for netting against debt requires review.','instant');
INSERT INTO "metrics" VALUES('staff_cost','Reported employee cost. Separately disclosed incentives may be excluded; see staff_incentives.','duration');
INSERT INTO "metrics" VALUES('staff_incentives','Separate incentive/profit-sharing expense; additional to staff_cost in the affected report.','duration');
INSERT INTO "metrics" VALUES('total_investments','Investments across maturities; do not assume all immediately liquid.','instant');
